content:
更新：确切的说，并不需要C的matrix3D为空，但是如果要在一个C的内部使Mask正常显示，则必须使该C内部的所有显示对象matrix3D均为空。以下是弹幕测试代码。
var C = $.createCanvas({x:playerWidth/2,y:playerHeight/2,lifeTime:0x7FFFFFF});
C.rotationX = -45;
var rC = $.createCanvas({lifeTime:0x7FFFFFF});
var BG = $.createShape({lifeTime:0x7FFFFFF});
BG.graphics.beginFill(0xFFFFFF);
BG.graphics.drawCircle(0,0,100);
var Masked = $.createShape({lifeTime:0x7FFFFFF});
Masked.graphics.beginFill(0xFF0000);
Masked.graphics.drawCircle(0,0,100);
var Mask = $.createShape({lifeTime:0x7FFFFFF});
Mask.graphics.beginFill(0xFF0000);
Mask.graphics.drawRect(0,0,100,100);
rC.addChild(BG);
rC.addChild(Masked);
rC.addChild(Mask);
Masked.mask = Mask;
C.addChild(rC);
$.root.addChild(C);
Masked.transform.matrix3D = null;
Mask.transform.matrix3D = null;
BG.transform.matrix3D = null;//去除此句Mask显示仍将不正常
要进行测试，可以把上面的代码加到你的程序的尾部，然后在newFrame函数中加上这几句：
rC.rotation++;
C.rotation++;
rC.rotationX++;
C.rotationX++;
rC.rotationY++;
C.rotationY++;
rC.rotationZ++;
C.rotationZ++;

即可看到一个超级复杂的遮罩旋转。

对这个遮罩bug的最终解决办法：同时注销Container、Mask、MaskedObject三者的3D变换。
Container.transform.matrix3D = null;
Mask.transform.matrix3D = null;
MaskedObject.transform.matrix3D = null;

我已经弄清楚遮罩bug是怎么一回事了。这是FlashPlayer的固有问题。一旦对被遮罩物体赋了任何z轴坐标值,遮罩显示立即就变成你的图那样。然而Bilibili的CommentShape类以及CommentCanvas类在创建时会自动初始化z轴值，于是乎就变成那样了。‘

测试代码：（在FP中运行）
var container:Sprite = new Sprite();

var wcircle:Sprite = new Sprite();
wcircle.graphics.beginFill(0xffffff);
wcircle.graphics.drawCircle(0,0,100);
container.addChild(wcircle);

var rcircle:Sprite = new Sprite();
rcircle.graphics.beginFill(0xff0000);
rcircle.graphics.drawCircle(0,0,100);
container.addChild(rcircle);

var squ:Sprite = new Sprite();
squ.graphics.beginFill(0x0000ff);
squ.graphics.drawRect(0,0,100,100);
container.addChild(squ);

rcircle.mask = squ;
【rcircle.z=0;】

addChild(container);
container.x = 320;
container.y = 240;

function rotate(e:Event){
	container.rotation++;
}
addEventListener(Event.ENTER_FRAME,rotate);
